// Copyright Sierra

import { useState } from "react";
import type { AttachmentHandlerOpts, MessageAttachment } from "@sierra/web";
import { ChatImage } from "./chat-image";
import { mockAttachmentOpts, reactDeclaration } from "./util";
import { PlaceholderImageSVG } from "./placeholder-image";

export const CarouselDeclaration = reactDeclaration<CarouselAttachmentPayload>({
    type: "carousel",
    name: "Carousel",
    description: "A horizontal carousel of product cards",
    schema: `{
    entries: {
        image: string;
        title?: string;
        subtitles?: string[];
        url?: string;
        buttons?: {
            label: string;
            action:
                | { type: "selectable"; selectedLabel: string }
                | {
                      type: "send-message";
                      message: { text: string; attachments?: MessageAttachment[] };
                  }
                | { type: "open-link"; link: string };
        }[];
    }[];
    submitSelectionLabel?: string;
}`,
    renderPreview: data => {
        const props = data ?? {
            type: "carousel" as const,
            entries: Array.from({ length: 3 }).map((_v, idx) => ({
                image: <PlaceholderImageSVG />,
                title: `Product ${idx + 1}`,
                subtitles: [`Subtitle ${idx + 1}`],
                buttons: [
                    {
                        label: `Button ${idx + 1}`,
                        action: { type: "selectable", selectedLabel: "Selected" },
                    },
                ],
            })),
        };

        return <Carousel data={props} opts={mockAttachmentOpts()} />;
    },
    render: (data, opts) => {
        return <Carousel data={data} opts={opts} />;
    },
});

export type CarouselAttachmentPayload = {
    type: "carousel";
    entries: {
        image: string | React.ReactNode;
        title?: string;
        subtitles?: string[];
        url?: string;
        buttons?: {
            label: string;
            action:
                | { type: "selectable"; selectedLabel: string }
                | {
                      type: "send-message";
                      message: { text: string; attachments?: MessageAttachment[] };
                  }
                | { type: "open-link"; link: string };
        }[];
    }[];
    submitSelectionLabel?: string;
};

export function Carousel({
    data,
    opts,
    size = "medium",
    imgStyle,
}: {
    data: CarouselAttachmentPayload;
    opts: AttachmentHandlerOpts;
    size?: "small" | "medium" | "large";
    imgStyle?: React.CSSProperties;
}) {
    const { entries } = data;
    const [selected, setSelected] = useState<number[]>([]);

    const sizes = {
        small: "10rem",
        medium: "15rem",
        large: "18rem",
    };

    if (!opts.isLastMessage) {
        return <SubmittedCarousel data={data} imgStyle={imgStyle} />;
    }

    return (
        <div className="flex flex-col gap-2" style={{ margin: "0 -0.75rem" }}>
            <div className="w-full overflow-x-auto">
                <div
                    className="flex"
                    style={{
                        gap: "1rem",
                        width: "fit-content",
                        marginBottom: "0.25rem",
                        padding: "0 0.75rem",
                    }}
                >
                    {entries.map((entry, i) => (
                        <div
                            key={i}
                            className="flex flex-col"
                            style={{
                                width: sizes[size],
                                borderRadius: "0.75rem",
                                overflow: "hidden",
                                backgroundColor: "white",
                                gap: "0.75rem",
                                paddingBottom:
                                    (entry.buttons ?? entry.subtitles ?? entry.title)
                                        ? "0.75rem"
                                        : undefined,
                                borderColor: "#ECECEC",
                                borderWidth: "1px",
                            }}
                        >
                            {makeComponentClickable(
                                entry.url,
                                <>
                                    <ChatImage
                                        src={entry.image}
                                        maxHeight={sizes[size]}
                                        style={imgStyle}
                                    />
                                    {entry.title && (
                                        <div
                                            className="flex flex-col gap-1"
                                            style={{
                                                paddingLeft: "0.75rem",
                                                paddingRight: "0.75rem",
                                            }}
                                        >
                                            <div style={{ fontWeight: "500" }}>{entry.title}</div>
                                            {entry.subtitles && (
                                                <div
                                                    style={{
                                                        fontSize: "0.85rem",
                                                        color: "#605E5A",
                                                        whiteSpace: "pre-line",
                                                    }}
                                                >
                                                    {entry.subtitles.join("\n")}
                                                </div>
                                            )}
                                        </div>
                                    )}
                                </>
                            )}
                            {entry.buttons && (
                                <div
                                    className="flex w-full"
                                    style={{
                                        marginTop: "0.25rem",
                                        paddingLeft: "0.75rem",
                                        paddingRight: "0.75rem",
                                    }}
                                >
                                    {entry.buttons.map((button, buttonIdx) => (
                                        <Button
                                            key={buttonIdx}
                                            grow
                                            variant={selected.includes(i) ? "primary" : "secondary"}
                                            onClick={() => {
                                                if (button.action.type === "selectable") {
                                                    setSelected(prev =>
                                                        prev.includes(i)
                                                            ? prev.filter(j => j !== i)
                                                            : [...prev, i]
                                                    );
                                                    // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition
                                                } else if (button.action.type === "send-message") {
                                                    opts.sendMessage(
                                                        button.action.message.text,
                                                        button.action.message.attachments
                                                    );
                                                    // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition
                                                } else if (button.action.type === "open-link") {
                                                    window.open(button.action.link, "_blank");
                                                }
                                            }}
                                            label={
                                                button.action.type === "selectable"
                                                    ? selected.includes(i)
                                                        ? button.action.selectedLabel
                                                        : button.label
                                                    : button.label
                                            }
                                        />
                                    ))}
                                </div>
                            )}
                        </div>
                    ))}
                </div>
            </div>
            {data.submitSelectionLabel && (
                <div
                    style={{
                        visibility: selected.length === 0 ? "hidden" : undefined,
                        backgroundColor: "var(--chat-color-assistant-bubble)",
                        color: "var(--chat-color-assistant-text)",
                        stroke: "var(--chat-color-assistant-text)",
                        padding: "0.75rem",
                        margin: "0.75rem",
                        borderRadius: "0.75rem",
                    }}
                    className="flex justify-between items-center"
                >
                    <div className="flex items-center" style={{ gap: "0.5rem" }}>
                        <Checkmark />
                        {selected.length} selected
                    </div>
                    <Button
                        label={data.submitSelectionLabel}
                        variant="primary"
                        onClick={() => {
                            opts.sendMessage(
                                listToSentence(selected.map(idx => entries[idx].title ?? "")),
                                [
                                    {
                                        type: "custom",
                                        data: JSON.stringify({
                                            type: "submit-selection",
                                            entryIndices: selected,
                                        }),
                                    },
                                ]
                            );
                        }}
                    />
                </div>
            )}
        </div>
    );
}

const makeComponentClickable = (link: string | undefined, children: React.ReactNode) => {
    if (!link) {
        return children;
    }
    return (
        <a href={link} target="_blank" rel="noopener noreferrer">
            {children}
        </a>
    );
};

function listToSentence(list: string[]) {
    if (list.length === 0) {
        return "";
    }
    if (list.length === 1) {
        return list[0];
    }
    if (list.length === 2) {
        return list.join(" and ");
    }
    return `${list.slice(0, -1).join(", ")}, and ${list.slice(-1)[0]}`;
}

function SubmittedCarousel({
    data,
    imgStyle,
}: {
    data: CarouselAttachmentPayload;
    imgStyle?: React.CSSProperties;
}) {
    const { entries } = data;
    return (
        <div className="flex flex-col gap-2">
            <div className="w-full overflow-x-auto">
                <div className="flex" style={{ gap: "1rem", width: "fit-content" }}>
                    {entries.map((entry, i) => (
                        <div
                            key={i}
                            className="flex flex-col relative"
                            style={{
                                width: "4rem",
                                borderRadius: "0.75rem",
                                overflow: "hidden",
                                backgroundColor: "white",
                                gap: "0.75rem",
                                borderColor: "#ECECEC",
                                borderWidth: "1px",
                            }}
                        >
                            <ChatImage src={entry.image} style={imgStyle} />
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
}

function Checkmark() {
    return (
        <svg
            width="16"
            height="16"
            viewBox="-3 -3 16 16"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
        >
            <path
                d="M1 5.9285L3.90909 8.71422L9 1.28564"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
            />
        </svg>
    );
}

function Button({
    label,
    variant,
    onClick,
    grow,
}: {
    label: string;
    variant: "primary" | "secondary";
    onClick: () => void;
    grow?: boolean;
}) {
    return (
        <button
            style={{
                ...(variant === "primary"
                    ? {
                          backgroundColor: "var(--chat-color-assistant-text)",
                          color: "var(--chat-color-assistant-bubble)",
                          fontWeight: "500",
                          borderWidth: "1px",
                          borderColor: "transparent",
                      }
                    : {
                          borderWidth: "1px",
                          borderColor: "#E9E9E9",
                      }),
                borderRadius: "0.375rem",
                padding: "0.5rem 0.75rem",
                flexGrow: grow ? "1" : undefined,
            }}
            onClick={onClick}
        >
            {label}
        </button>
    );
}
